fn accepted(b:&[u8])->room::Room {let Reply::Accepted(r)=room::decode(b).unwrap() else{panic!("success expected")};r}
fn room_value(r:&room::Room)->Value {json!({"room_id":r.id,"name_hex":r.name.iter().map(|v|format!("{v:02x}")).collect::<String>(),"attributes":r.attributes,"password_hex":r.password.iter().map(|v|format!("{v:02x}")).collect::<String>(),"users":r.users_summary,"capacity":r.capacity,"mode":r.mode,"map_id":r.map_id,"summary":r.summary,"owner_hex":r.owner_alias.iter().map(|v|format!("{v:02x}")).collect::<String>(),"options":r.options,"selections":r.selections})}
fn ce_vector(name:&[u8],password:&[u8],owner:&[u8],selection:&[u8])->Vec<u8> {
 let mut b=vec![206,0];b.extend(0xf1234567u32.to_le_bytes());b.extend(name);b.extend([0,0xfc]);b.extend(password);b.push(0);
 b.extend(0xfedcu16.to_le_bytes());b.extend(0xabcdu16.to_le_bytes());b.push(0xfe);b.extend(0xbeefu16.to_le_bytes());b.extend([1,128,254,0,255]);b.extend(owner);b.push(0);b.extend([7,2,127,31]);b.push(selection.len()as u8);b.extend(selection);b
}
